===== discovery types.ts =====
// SPDX-License-Identifier: Apache-2.0
//
// The client-safe entry. Deliberately carries no side-effect import that would restrict this
// module to the server — a client component holds a resolved ServiceState as data, exactly as
// @paigasus/sdk's ./errors/types is exempted.
//
// Everything here must survive the RSC server-to-client boundary as plain data. That is why
// `capabilities` is a readonly array and not a ReadonlySet (a Set does not serialize), and why
// ServiceDescriptor is a plain structural type rather than protobuf-es's ServiceInfo message
// (which carries $typeName, and which apps are banned from naming — the
// `paigasus/boundaries/apps` eslint block bans @paigasus/proto including type imports).

/** A service's self-description, converted from `paigasus.common.v1.ServiceInfo`. */
export type ServiceDescriptor = {
  readonly service: string;
  readonly version: string;
  readonly capabilities: readonly string[];
};

/**
 * Why a configured service is not usable right now.
 *
 * A closed union, never free text: the UI branches on the code and never on a message.
 * This vocabulary is owned HERE and not imported from @paigasus/sdk — that package's
 * `Presentation` union cannot express these cases (spec F8).
 *
 * `DEGRADED_REASONS` is the single source of truth: `DegradedReason` is DERIVED from it, so a
 * runtime validator (`parseRecord` in core/record.ts) can check an untrusted value against the
 * real vocabulary without hand-duplicating the member list and risking drift.
 */
export const DEGRADED_REASONS = ['timeout', 'network', 'unauthorized', 'not-implemented', 'bad-response', 'server-error', 'cache-unavailable'] as const;

export type DegradedReason = (typeof DEGRADED_REASONS)[number];

export type ServiceState =
  | { readonly state: 'absent'; readonly service: string }
  | {
      readonly state: 'available';
      readonly service: string;
      readonly descriptor: ServiceDescriptor;
      readonly capabilities: readonly string[];
    }
  | {
      readonly state: 'degraded';
      readonly service: string;
      readonly reason: DegradedReason;
      readonly descriptor: ServiceDescriptor | null;
      readonly capabilities: readonly string[];
    };

export const SERVICE_STATES = ['absent', 'available', 'degraded'] as const;

/**
 * A capability key, as a CLOSED union.
 *
 * Hand-declared, and deliberately not `` `${string}.${string}` ``: that template accepts the typo
 * `iam.audits`, which at runtime returns false forever and silently hides a nav item — the
 * "invisible" failure the design calls worse than a wrongly-shown disabled one. Hand-declaring
 * re-opens a drift risk against the proto registry, and tests/vocabulary.test.ts closes it by
 * comparing these members against the registry-derived runtime list.
 *
 * It lives HERE and not in core/state.ts on purpose. This file is the client-safe entry, and
 * core/state.ts imports `@paigasus/proto` as a VALUE — re-exporting from it would pull
 * protobuf-es into any client bundle that imports `@paigasus/discovery/types`, and would route
 * around the `paigasus/boundaries/apps` eslint ban on apps importing `@paigasus/proto`, which
 * cannot see through a re-export.
 */
export type CapabilityKey = 'iam.authz.cedar' | 'iam.apikeys' | 'iam.audit' | 'gateway.chat.stream';
===== app-shell app-shell.tsx props =====
// SPDX-License-Identifier: Apache-2.0
'use client';

import type { ReactElement, ReactNode } from 'react';
import { cn } from '@paigasus/ui';
import { PrimaryNav, type NavEntry } from '../nav/primary-nav';
import { ZoneLink } from '../zone/zone-link';
import { MAIN_ID, SkipLink } from './skip-link';
import { Switcher, type SwitcherProps } from './switcher';
import { UserMenu } from './user-menu';

/*
 * Sentinel C (SMA-511 spec § 7.6). SOURCE_PROBE's value, below, is an arbitrary custom-property
 * utility that exists ONLY there, and it compiles to a single declaration in the built CSS.
 * ci/tailwind-source/run.mjs asserts it reaches the iam-console production build, which is what
 * proves the app's Tailwind `@source` line still covers this package.
 *
 * It follows @paigasus/ui's sentinel A (src/components/table.tsx). Do not remove it, do not rename
 * it, and do not write its literal value anywhere else in this file or under ts/apps/ — Tailwind's
 * scanner reads raw file text, comments included, so a second copy (even in prose) could generate
 * the utility independently and silently disarm the gate. That is why this comment does not spell
 * out the literal itself; see the assignment below, or run.mjs's PROBE_APP_SHELL.
 */
const SOURCE_PROBE = '[--paigasus-app-shell-source-probe:1]';

export type Brand = {
  readonly label: string;
  /** A full path (spec § 6.2). */
  readonly href: string;
};

export type AppShellProps = {
  readonly brand: Brand;
  readonly nav: readonly NavEntry[];
  /** One Switcher per level (org, team). */
  readonly switchers?: readonly SwitcherProps[];
  readonly children: ReactNode;
};

/**
 * The authenticated shell (spec § 8.1). It must be rendered under BOTH ZoneProvider and
 * SessionProvider. UserMenu and PrimaryNav call useSession(), so without a SessionProvider this
 * throws, which makes a missing provider loud. It takes no breadcrumbs: a page renders its own.
 */
export function AppShell({ brand, nav, switchers, children }: AppShellProps): ReactElement {
  return (
    <>
      <SkipLink />
      <header className={cn(SOURCE_PROBE, 'flex flex-wrap items-center gap-4 border-b border-border bg-background px-4 py-2')}>
        <ZoneLink href={brand.href} className="font-semibold">
          {brand.label}
        </ZoneLink>
        <PrimaryNav entries={nav} />
        <div className="ml-auto flex items-center gap-2">
          {switchers?.map((switcher) => (
            <Switcher key={switcher.label} label={switcher.label} items={switcher.items} currentId={switcher.currentId} />
          ))}
          <UserMenu />
        </div>
      </header>
      <main id={MAIN_ID} tabIndex={-1} className="outline-none">
        {children}
      </main>
    </>
  );
}

