   109	  }
   110	  return { ...env, ...values };
   111	}
   112	
   113	/** Runs every close step in order, also after one throws, so one failed step cannot leak the rest. */
   114	async function closeInOrder(steps: readonly (() => Promise<void>)[]): Promise<void> {
   115	  const failures: unknown[] = [];
   116	  for (const step of steps) {
   117	    try {
   118	      await step();
   119	    } catch (error) {
   120	      failures.push(error);
   121	    }
   122	  }
   123	  if (failures.length > 0) throw new AggregateError(failures, `${String(failures.length)} of ${String(steps.length)} close steps failed`);
   124	}
   125	
   126	async function startStack(): Promise<{ harness: Harness; close: () => Promise<void> }> {
   127	  const tls = testTls();
   128	  // Everything that started so far, NEWEST FIRST: the order to close it in. A start step that
   129	  // throws closes all of it before the error goes up. waitForHealth throws on a 5xx answer and at
   130	  // its timeout, and the worker fixture gets no `close` from a start that threw. Without this, the
   131	  // server.js child, the terminator and both fakes stay alive after a failed start.
   132	  const started: (() => Promise<void>)[] = [];
   133	  try {
   134	    const idp = await startFakeIdp({ cert: tls });
   135	    started.unshift(() => idp.close());
   136	    const iam = await startFakeIam({ handlers: worldHandlers() });
   137	    started.unshift(() => iam.close());
   138	    iam.setServiceInfo(DEFAULT_DESCRIPTOR);
   139	
   140	    let output = '';
   141	    const failures: string[] = [];
   142	    for (let attempt = 1; attempt <= MAX_START_ATTEMPTS; attempt += 1) {
   143	      const port = await freePort();
   144	      const terminator = await startTlsTerminator({ target: `http://127.0.0.1:${String(port)}`, tls });
   145	      const closeTerminator = (): Promise<void> => terminator.close();
   146	      started.unshift(closeTerminator);
   147	      output = '';
   148	      const child = spawn(process.execPath, [path.join(STANDALONE_APP_DIR, 'server.js')], {
   149	        cwd: STANDALONE_APP_DIR,
   150	        stdio: ['ignore', 'pipe', 'pipe'],
   151	        env: serverEnv({
   152	          PORT: String(port),
   153	          HOSTNAME: '127.0.0.1',
   154	          NEXT_TELEMETRY_DISABLED: '1',
   155	          NODE_EXTRA_CA_CERTS: tls.certPath,
   156	          PAIGASUS_ZONE: 'iam',
   157	          PAIGASUS_ZONES: JSON.stringify({ iam: '/iam' }),
   158	          PAIGASUS_OIDC_ISSUER: idp.issuer,
   159	          PAIGASUS_OIDC_CLIENT_ID: idp.clientId,
   160	          PAIGASUS_OIDC_CLIENT_SECRET: idp.clientSecret,
   161	          PAIGASUS_PUBLIC_ORIGIN: terminator.origin,
   162	          PAIGASUS_SESSION_STORE: 'memory',
   163	          PAIGASUS_SERVICES: JSON.stringify({ iam: iam.httpUrl }),
   164	          PAIGASUS_IAM_GRPC_URL: iam.grpcUrl,
   165	          PAIGASUS_DISCOVERY_NEGATIVE_MS: '1',
   166	          PAIGASUS_DISCOVERY_FRESH_MS: '2',
   167	          PAIGASUS_DISCOVERY_STALE_MS: '3',
   168	        }),
   169	      });
   170	      const stopChild = (): Promise<void> => stop(child);
   171	      started.unshift(stopChild);
   172	      child.stdout?.on('data', (chunk: Buffer) => {
   173	        output += chunk.toString('utf8');
   174	      });
   175	      child.stderr?.on('data', (chunk: Buffer) => {
   176	        output += chunk.toString('utf8');
   177	      });
   178	
   179	      const state = await waitForHealth(`http://127.0.0.1:${String(port)}/iam/healthz`, child, () => output);
   180	      if (state === 'ready') {
   181	        const harness: Harness = {
   182	          origin: terminator.origin,
   183	          iam,
   184	          idp,
   185	          url: (fullPath) => `${terminator.origin}${fullPath}`,
   186	          serverOutput: () => output,
   187	          useWorld: (options = {}) => {
   188	            iam.setHandlers(worldHandlers(options));
   189	            iam.setServiceInfo(options.descriptor ?? DEFAULT_DESCRIPTOR);
   190	          },
   191	        };
   192	        // The server, then the terminator in front of it, then the fake IAM and the fake IdP.
   193	        return { harness, close: () => closeInOrder(started.splice(0)) };
   194	      }
   195	      failures.push(`attempt ${String(attempt)}: the server exited before it answered\n${output}`);
   196	      // This attempt's server exited first (a port race). Remove its two entries (the newest two)
   197	      // and close them. The fakes stay up for the next attempt.
   198	      started.splice(0, 2);
   199	      await closeInOrder([stopChild, closeTerminator]);
   200	    }
   201	    throw new Error(`the iam-console server failed to start after ${String(MAX_START_ATTEMPTS)} attempts:\n${failures.join('\n')}`);
   202	  } catch (error) {
   203	    // Close what started, then rethrow the START error: it tells why the stack is not up. A close
   204	    // failure goes to stderr, because it must not hide the start error.
   205	    await closeInOrder(started.splice(0)).catch((closeError: unknown) => {
   206	      console.error('the e2e stack failed to start, and closing what had started failed too:', closeError);
   207	    });
   208	    throw error;
   209	  }
   210	}
   211	
   212	export const test = base.extend<{ world: undefined }, { harness: Harness }>({
   213	  harness: [
   214	    // eslint-disable-next-line no-empty-pattern -- Playwright requires an object pattern as the first argument.
   215	    async ({}, use) => {
   216	      const { harness, close } = await startStack();
   217	      try {
   218	        await use(harness);
   219	      } finally {
   220	        await close();
   221	      }
   222	    },
   223	    // CI ONLY: MAX_START_ATTEMPTS (3) * READY_TIMEOUT_MS, plus room for the fakes and the
   224	    // terminator, so a widened READY_TIMEOUT_MS on a loaded runner cannot outrun this wrapper.
   225	    { scope: 'worker', timeout: isCI ? 420_000 : 180_000 },
