     1	// SPDX-License-Identifier: Apache-2.0
     2	//
     3	// The e2e stack, ONE per worker (workers: 1, so one per run; Playwright starts a new worker, and
     4	// with it a new stack, after a failed test):
     5	//
     6	//   browser --https--> TLS terminator --http--> standalone server.js --h2c--> fake IAM (gRPC)
     7	//                                                    |  \--http--> fake IAM (GET /v1/service-info)
     8	//                                                    \--https--> fake IdP (NODE_EXTRA_CA_CERTS)
     9	//
    10	// The terminator forwards Host and sets X-Forwarded-Proto: https, so PAIGASUS_PUBLIC_ORIGIN is a
    11	// real https origin, the __Host- cookies work, and Next's Server Action origin check passes.
    12	import { spawn, type ChildProcess } from 'node:child_process';
    13	import { once } from 'node:events';
    14	import { createServer } from 'node:net';
    15	import path from 'node:path';
