    17	import { startFakeIam, startFakeIdp, startTlsTerminator, testTls, type FakeIam, type FakeIdp } from '@paigasus/console-core/testing';
    18	import { STANDALONE_APP_DIR } from './paths';
    19	import { DEFAULT_DESCRIPTOR, worldHandlers, type WorldOptions } from './world';
    20	
    21	// CI ONLY. PR #237's `moon ci` run showed the e2e tier flaking under CI's concurrent load (Rust
    22	// compiles plus four `test-e2e` tasks at once). This bound is not one of the three observed
    23	// failures, but the same loaded runner can just as well stretch out server start-up, so it is
    24	// raised here too, on the same reasoning: local keeps its tight 60 s bound, CI gets more room. The
    25	// worker fixture's own `timeout` below is widened to match, since it wraps up to
    26	// MAX_START_ATTEMPTS retries of this wait.
    27	const isCI = !!process.env.CI;
    28	const READY_TIMEOUT_MS = isCI ? 120_000 : 60_000;
    29	const PROBE_TIMEOUT_MS = 2_000;
    30	const STOP_TIMEOUT_MS = 5_000;
    31	const MAX_START_ATTEMPTS = 3;
    32	
    33	export type Harness = {
    34	  readonly origin: string;
    35	  readonly iam: FakeIam;
    36	  readonly idp: FakeIdp;
    37	  /** `origin + path`. `path` is the full path the browser sees, for example `/iam/orgs`. */
    38	  url(path: string): string;
    39	  /** Everything the server wrote to stdout and stderr since it started. */
    40	  serverOutput(): string;
    41	  /** Script the fake IAM for the current test. The auto fixture below resets it before each test. */
    42	  useWorld(options?: WorldOptions): void;
    43	};
    44	
    45	function freePort(): Promise<number> {
    46	  return new Promise((resolve, reject) => {
    47	    const probe = createServer();
    48	    probe.once('error', reject);
    49	    probe.listen(0, '127.0.0.1', () => {
    50	      const address = probe.address();
    51	      if (address === null || typeof address === 'string') {
    52	        probe.close();
    53	        reject(new Error('could not read the probe port'));
    54	        return;
    55	      }
    56	      probe.close(() => resolve(address.port));
    57	    });
    58	  });
    59	}
    60	
    61	async function stop(child: ChildProcess): Promise<void> {
    62	  if (child.exitCode !== null || child.signalCode !== null) return;
    63	  const exited = once(child, 'exit').then(() => 'exited' as const);
    64	  child.kill('SIGTERM');
    65	  let timeoutHandle: NodeJS.Timeout | undefined;
    66	  const timeout = new Promise<'timeout'>((resolve) => {
    67	    timeoutHandle = setTimeout(() => resolve('timeout'), STOP_TIMEOUT_MS);
    68	  });
    69	  try {
    70	    if ((await Promise.race([exited, timeout])) === 'timeout') {
    71	      child.kill('SIGKILL');
    72	      await exited;
    73	    }
    74	  } finally {
    75	    clearTimeout(timeoutHandle);
    76	  }
    77	}
    78	
    79	/** 'ready', or 'exited' when the process died first (a port race: the caller retries). */
    80	async function waitForHealth(url: string, child: ChildProcess, output: () => string): Promise<'ready' | 'exited'> {
    81	  const deadline = Date.now() + READY_TIMEOUT_MS;
    82	  while (Date.now() < deadline) {
    83	    if (child.exitCode !== null || child.signalCode !== null) return 'exited';
    84	    try {
    85	      const response = await fetch(url, { signal: AbortSignal.timeout(PROBE_TIMEOUT_MS) });
    86	      if (response.ok) return 'ready';
    87	      // A 500 here is a config parse failure at first request. It never recovers: fail now.
    88	      if (response.status >= 500) throw new Error(`GET ${url} answered ${String(response.status)}\n--- server output ---\n${output()}`);
    89	    } catch (error) {
    90	      if (error instanceof Error && error.message.startsWith('GET ')) throw error;
    91	      // Not listening yet, or the probe timed out.
    92	    }
    93	    await new Promise((resolve) => setTimeout(resolve, 250));
    94	  }
    95	  throw new Error(`the iam-console server did not answer ${url} within ${String(READY_TIMEOUT_MS)} ms\n--- server output ---\n${output()}`);
    96	}
    97	
    98	/**
    99	 * The parent's env minus anything that could leak into or mis-configure the server.
   100	 *
   101	 * NODE_ENV is STATED, not inherited: this is a production build, and the parent runs under the
   102	 * Playwright runner. Next's type augmentation also makes the key required on ProcessEnv.
   103	 */
   104	function serverEnv(values: Readonly<Record<string, string>>): NodeJS.ProcessEnv {
   105	  const env: NodeJS.ProcessEnv = { NODE_ENV: 'production' };
   106	  for (const [key, value] of Object.entries(process.env)) {
   107	    if (key === 'NODE_ENV' || key.startsWith('PAIGASUS_') || key.startsWith('__NEXT')) continue;
   108	    env[key] = value;
   109	  }
   110	  return { ...env, ...values };
   111	}
   112	
   113	/** Runs every close step in order, also after one throws, so one failed step cannot leak the rest. */
   114	async function closeInOrder(steps: readonly (() => Promise<void>)[]): Promise<void> {
   115	  const failures: unknown[] = [];
   116	  for (const step of steps) {
   117	    try {
   118	      await step();
   119	    } catch (error) {
   120	      failures.push(error);
   121	    }
   122	  }
   123	  if (failures.length > 0) throw new AggregateError(failures, `${String(failures.length)} of ${String(steps.length)} close steps failed`);
   124	}
   125	
   126	async function startStack(): Promise<{ harness: Harness; close: () => Promise<void> }> {
   127	  const tls = testTls();
   128	  // Everything that started so far, NEWEST FIRST: the order to close it in. A start step that
   129	  // throws closes all of it before the error goes up. waitForHealth throws on a 5xx answer and at
   130	  // its timeout, and the worker fixture gets no `close` from a start that threw. Without this, the
   131	  // server.js child, the terminator and both fakes stay alive after a failed start.
   132	  const started: (() => Promise<void>)[] = [];
   133	  try {
   134	    const idp = await startFakeIdp({ cert: tls });
   135	    started.unshift(() => idp.close());
   136	    const iam = await startFakeIam({ handlers: worldHandlers() });
   137	    started.unshift(() => iam.close());
   138	    iam.setServiceInfo(DEFAULT_DESCRIPTOR);
   139	
   140	    let output = '';
   141	    const failures: string[] = [];
   142	    for (let attempt = 1; attempt <= MAX_START_ATTEMPTS; attempt += 1) {
   143	      const port = await freePort();
   144	      const terminator = await startTlsTerminator({ target: `http://127.0.0.1:${String(port)}`, tls });
   145	      const closeTerminator = (): Promise<void> => terminator.close();
   146	      started.unshift(closeTerminator);
   147	      output = '';
   148	      const child = spawn(process.execPath, [path.join(STANDALONE_APP_DIR, 'server.js')], {
   149	        cwd: STANDALONE_APP_DIR,
   150	        stdio: ['ignore', 'pipe', 'pipe'],
   151	        env: serverEnv({
   152	          PORT: String(port),
   153	          HOSTNAME: '127.0.0.1',
   154	          NEXT_TELEMETRY_DISABLED: '1',
   155	          NODE_EXTRA_CA_CERTS: tls.certPath,
   156	          PAIGASUS_ZONE: 'iam',
   157	          PAIGASUS_ZONES: JSON.stringify({ iam: '/iam' }),
   158	          PAIGASUS_OIDC_ISSUER: idp.issuer,
   159	          PAIGASUS_OIDC_CLIENT_ID: idp.clientId,
   160	          PAIGASUS_OIDC_CLIENT_SECRET: idp.clientSecret,
   161	          PAIGASUS_PUBLIC_ORIGIN: terminator.origin,
   162	          PAIGASUS_SESSION_STORE: 'memory',
   163	          PAIGASUS_SERVICES: JSON.stringify({ iam: iam.httpUrl }),
   164	          PAIGASUS_IAM_GRPC_URL: iam.grpcUrl,
   165	          PAIGASUS_DISCOVERY_NEGATIVE_MS: '1',
   166	          PAIGASUS_DISCOVERY_FRESH_MS: '2',
   167	          PAIGASUS_DISCOVERY_STALE_MS: '3',
   168	        }),
   169	      });
