   179	      const state = await waitForHealth(`http://127.0.0.1:${String(port)}/iam/healthz`, child, () => output);
   180	      if (state === 'ready') {
   181	        const harness: Harness = {
   182	          origin: terminator.origin,
   183	          iam,
   184	          idp,
   185	          url: (fullPath) => `${terminator.origin}${fullPath}`,
   186	          serverOutput: () => output,
