  5	// PAIGASUS_ZONES must answer different zone maps on `GET /iam/healthz`, which is public and runs the
  6	// FULL configuration parse. If Next had inlined a value, or the standalone trace had dropped a
  7	// package, both boots would agree — and every unit test in this repo would still pass.
  8	//
  9	// Each boot gets a COMPLETE, valid environment, so a failure can only come from what a case
 10	// changes. The mismatch case asserts the mismatch MESSAGE in the server output, not only a 500: a
 11	// missing unrelated variable also answers 500, and must not pass it.
 12	import { spawn, type ChildProcess } from 'node:child_process';
 13	import { createServer } from 'node:net';
 14	import { fileURLToPath } from 'node:url';
 15	import { describe, expect, it } from 'vitest';
 16	
 17	const SERVER_ENTRY = fileURLToPath(new URL('../.next/standalone/apps/iam-console/server.js', import.meta.url));
 18	
 19	const COMPLETE_ENV: Readonly<Record<string, string>> = {
 20	  PAIGASUS_ZONE: 'iam',
 21	  PAIGASUS_OIDC_ISSUER: 'https://idp.example.test',
 22	  PAIGASUS_OIDC_CLIENT_ID: 'console',
 23	  PAIGASUS_OIDC_CLIENT_SECRET: 'console-secret',
 24	  PAIGASUS_PUBLIC_ORIGIN: 'https://console.example.test',
 25	  PAIGASUS_SESSION_STORE: 'memory',
 26	  PAIGASUS_SERVICES: '{"iam":"http://127.0.0.1:9"}',
 27	  PAIGASUS_IAM_GRPC_URL: 'http://127.0.0.1:9',
 28	};
 29	
 30	async function freePort(): Promise<number> {
 31	  return await new Promise((resolve, reject) => {
 32	    const srv = createServer();
 33	    srv.once('error', reject);
 34	    srv.listen(0, '127.0.0.1', () => {
 35	      const address = srv.address();
 36	      if (address === null || typeof address === 'string') {
 37	        reject(new Error('could not acquire a port'));
 38	        return;
 39	      }
 40	      const { port } = address;
 41	      srv.close(() => resolve(port));
 42	    });
 43	  });
 44	}
 45	
 46	type Answer = { status: number; body: string; output: string };
 47	
 48	// The child is OBSERVED, not merely polled (the reasons are recorded in this file's history): an
 49	// early death is reported as a death, both streams are drained so a chatty child cannot block, and
 50	// a deadline still covers a process that starts and never listens. `waitForOutput` keeps the server
 51	// alive until its log contains that text, because Next writes a route error to stderr around the
 52	// time it sends the 500.
 53	async function healthzWith(zones: Record<string, string>, waitForOutput?: string): Promise<Answer> {
 54	  const port = await freePort();
 55	  const child: ChildProcess = spawn(process.execPath, [SERVER_ENTRY], {
 56	    env: { ...process.env, ...COMPLETE_ENV, PORT: String(port), HOSTNAME: '127.0.0.1', PAIGASUS_ZONES: JSON.stringify(zones) },
 57	    stdio: 'pipe',
 58	  });
 59	
 60	  let output = '';
 61	  const capture = (chunk: Buffer | string): void => {
 62	    output += String(chunk);
 63	  };
 64	  child.stdout?.on('data', capture);
 65	  child.stderr?.on('data', capture);
 66	
 67	  let died: string | undefined;
 68	  child.once('error', (err: Error) => {
 69	    died = `the server process failed to start: ${err.message}`;
 70	  });
 71	  child.once('exit', (code, signal) => {
 72	    died = `the server process exited before answering (code ${String(code)}, signal ${String(signal)})`;
 73	  });
 74	
 75	  const withOutput = (message: string): Error => new Error(`${message}\n--- server output ---\n${output.trim() === '' ? '(none captured)' : output}`);
 76	
 77	  try {
 78	    const deadline = Date.now() + 60_000;
 79	    for (;;) {
 80	      if (died !== undefined) throw withOutput(died);
 81	      if (Date.now() > deadline) throw withOutput('standalone server did not become ready within 60s');
 82	      let res: Response | undefined;
 83	      try {
 84	        res = await fetch(`http://127.0.0.1:${String(port)}/iam/healthz`, { signal: AbortSignal.timeout(5_000) });
 85	      } catch {
 86	        // not listening yet, or this attempt hung and timed out
 87	      }
 88	      if (res !== undefined) {
 89	        const answer = { status: res.status, body: await res.text() };
 90	        const logDeadline = Date.now() + 5_000;
 91	        while (waitForOutput !== undefined && !output.includes(waitForOutput) && Date.now() < logDeadline) {
 92	          await new Promise((r) => setTimeout(r, 100));
 93	        }
 94	        return { ...answer, output };
 95	      }
 96	      await new Promise((r) => setTimeout(r, 250));
 97	    }
 98	  } finally {
 99	    if (child.exitCode === null && child.signalCode === null) child.kill('SIGTERM');
100	  }
101	}
102	
103	describe('the standalone server reads configuration at runtime', () => {
104	  it('serves different zone maps from the SAME binary', async () => {
105	    const first = await healthzWith({ iam: '/iam', gateway: '/gateway' });
106	    const second = await healthzWith({ iam: '/iam', reports: '/reports' });
107	
108	    expect(first.status).toBe(200);
109	    expect(second.status).toBe(200);
110	    expect(JSON.parse(first.body)).toEqual({ zone: 'iam', zones: { iam: '/iam', gateway: '/gateway' } });
111	    expect(JSON.parse(second.body)).toEqual({ zone: 'iam', zones: { iam: '/iam', reports: '/reports' } });
112	  });
113	
114	  it('fails loudly, with the mismatch message, when the deployed prefix disagrees with the compiled one', async () => {
115	    const message = 'Base path mismatch for zone "iam"';
116	    const result = await healthzWith({ iam: '/admin/iam' }, message);
117	    expect(result.status).toBe(500);
118	    expect(result.output).toContain(message);
119	  });
120	});

