     1	// SPDX-License-Identifier: Apache-2.0
     2	//
     3	// lib/console.ts's ONE createConsoleRuntime() call, read as TEXT (SMA-512). A future edit could
     4	// turn that module-scope call into something lazy, partial, or built from the wrong pieces — in
     5	// particular, it could pass the imported `authRuntime` binding straight through instead of a fresh
     6	// arrow, which would reintroduce the TDZ hazard CLAUDE.md records for this pair of modules
     7	// (SMA-511). No unit or integration test can observe the runtime consequence of either mistake
     8	// directly (createConsoleRuntime's accessors are React cache() wrappers, a pass-through outside a
     9	// server render), so this test asserts the SOURCE shape instead.
    10	import { readFileSync } from 'node:fs';
    11	import { describe, expect, it } from 'vitest';
    12	
    13	const source = readFileSync(new URL('../../lib/console.ts', import.meta.url), 'utf8');
    14	
    15	// lib/console.ts's own header comment QUOTES the exact call-site shape this suite pins
    16	// ("authRuntime: () => authRuntime()"), as prose explaining why the call site is written that
    17	// way. MEASURED: a plain regex over `source` matches that prose even when the call site itself
    18	// regresses to the bare imported binding (`authRuntime,`), because the comment string survives
    19	// untouched. The fresh-arrow assertion below therefore runs against comment-stripped source, so it
    20	// binds to the call site and not to documentation about the call site.
    21	const codeOnly = source
    22	  .split('\n')
    23	  .filter((line) => !line.trim().startsWith('//'))
    24	  .join('\n');
    25	
    26	describe('lib/console.ts composes the runtime exactly once, correctly', () => {
    27	  it('calls createConsoleRuntime exactly once', () => {
    28	    expect(source.match(/createConsoleRuntime\s*\(/g) ?? []).toHaveLength(1);
    29	  });
    30	
    31	  it('calls it at module scope, not inside a function', () => {
    32	    expect(source).toMatch(/^export const \{[^}]*\} = createConsoleRuntime\(/m);
    33	  });
    34	
    35	  it('re-exports every accessor the app uses', () => {
    36	    for (const name of ['currentSession', 'optionalSession', 'sessionToken', 'iamClients', 'iamClientsForAction', 'iamClientsForToken', 'currentPrincipal', 'mayI', 'myScopes', 'discovery']) {
    37	      expect(source).toContain(name);
    38	    }
    39	  });
    40	
    41	  it('passes the auth runtime as a fresh arrow, not the imported binding', () => {
    42	    expect(codeOnly).toMatch(/authRuntime:\s*\(\)\s*=>\s*authRuntime\(\)/);
    43	  });
    44	});
