  1	// SPDX-License-Identifier: Apache-2.0
  2	//
  3	// ADR-0017: the browser never receives a token. Every response the page receives in a signed-in
  4	// session is collected: HTML documents and RSC payloads (navigations and prefetches) alike. None
  5	// may contain the access or the refresh token the fake IdP issued.
  6	//
  7	// This zone has no Server Action (spec § 13: the scope route changes only the URL and the
  8	// breadcrumbs), so this is the HTML/RSC half of iam-console's tests/e2e/token-leak.spec.ts, with no
  9	// action guard. EVERY RSC BODY IS BUFFERED BY THIS TEST, not read from Playwright afterwards, for
 10	// the same measured reason iam-console's copy documents: a client navigation's RSC GET can arrive
 11	// with `bodySize: -1`, and `response.body()` then rejects or hangs under load. `page.route` fetches
 12	// those responses, reads their text in this process, and fulfils each request with the same bytes,
 13	// so the scan never depends on Playwright retaining a streamed body.
 14	import type { Request, Response } from '@playwright/test';
 15	import { ORG_ID } from './support/world';
 16	import { signIn, waitForHydration } from './support/login';
 17	import { expect, test } from './support/harness';
 18	
 19	type Seen = {
 20	  readonly url: string;
 21	  readonly method: string;
 22	  readonly contentType: string;
 23	  /** false for a redirect, which carries no body. The residue assertion ignores those. */
 24	  readonly expectsBody: boolean;
 25	  /** true only after the body was read. */
 26	  readonly bodyRead: boolean;
 27	  /** true when the body came from the route interceptor, not from `response.body()`. */
 28	  readonly buffered: boolean;
 29	  /** The one class the row may leave unread, when the interceptor could not buffer it. */
 30	  readonly prefetchRsc: boolean;
 31	  readonly body: string;
 32	  /** The headers and the body: what the leak scan searches. */
 33	  readonly text: string;
 34	};
 35	
 36	/**
 37	 * The LAST-RESORT class of response whose body this row may leave unread, matched POSITIVELY on
 38	 * the request: `Next-Router-Prefetch: 1` together with the `_rsc=` query the router adds. See
 39	 * iam-console's token-leak.spec.ts for the measurement this mirrors.
 40	 */
 41	async function isPrefetchRsc(response: Response): Promise<boolean> {
 42	  const request = response.request();
 43	  const headers = await request.allHeaders();
 44	  return headers['next-router-prefetch'] === '1' && new URL(request.url()).searchParams.has('_rsc');
 45	}
 46	
 47	/** An RSC payload fetch: the GET the App Router makes for a client navigation or a prefetch. */
 48	function isRscGet(request: Request): boolean {
 49	  return request.method() === 'GET' && new URL(request.url()).searchParams.has('_rsc');
 50	}
 51	
 52	async function capture(response: Response, buffered: ReadonlyMap<Request, string>): Promise<Seen> {
 53	  const request = response.request();
 54	  const headers = await response.allHeaders();
 55	  const status = response.status();
 56	  const expectsBody = status < 300 || status >= 400;
 57	  const prefetchRsc = await isPrefetchRsc(response);
 58	  const fromRoute = buffered.get(request);
 59	  let body = fromRoute ?? '';
 60	  let bodyRead = fromRoute !== undefined;
 61	  if (!bodyRead && expectsBody && !prefetchRsc) {
 62	    try {
 63	      body = (await response.body()).toString('utf8');
 64	      bodyRead = true;
 65	    } catch {
 66	      // The read failed. bodyRead stays false, so no vacuity guard counts this response as
 67	      // scanned AND the residue assertion reports it.
 68	    }
 69	  }
 70	  return {
 71	    url: response.url(),
 72	    method: request.method(),
 73	    contentType: headers['content-type'] ?? '',
 74	    expectsBody,
 75	    bodyRead,
 76	    buffered: fromRoute !== undefined,
 77	    prefetchRsc,
 78	    body,
 79	    text: `${JSON.stringify(headers)}\n${body}`,
 80	  };
 81	}
 82	
 83	/** true when the body was read and is not empty, so the leak scan searched it. */
 84	function scanned(response: Seen): boolean {
 85	  return response.bodyRead && response.body.length > 0;
 86	}
 87	
 88	test('R5: no response body, header or RSC payload contains a fake token (ADR-0017)', async ({ page, harness }) => {
 89	  // The buffered bodies, keyed by the Request the response carries — the SAME object the route
 90	  // handler saw, so no url or timing match is needed.
 91	  const buffered = new Map<Request, string>();
 92	  // Only same-origin RSC GETs are intercepted. Documents and static assets fall through untouched,
 93	  // so the interception cannot change how the page loads.
 94	  await page.route(
 95	    (url) => url.origin === harness.origin && url.searchParams.has('_rsc'),
 96	    async (route) => {
 97	      const request = route.request();
 98	      if (!isRscGet(request)) {
 99	        await route.fallback();
100	        return;
101	      }
102	      try {
103	        // maxRedirects: 0 — the browser must see a redirect as a redirect.
104	        const answer = await route.fetch({ maxRedirects: 0 });
105	        const text = await answer.text();
106	        buffered.set(request, text);
107	        const headers = { ...answer.headers() };
108	        delete headers['content-encoding'];
109	        delete headers['content-length'];
110	        await route.fulfill({ status: answer.status(), headers, body: text });
111	      } catch {
112	        // The router cancelled the request, or the page closed. Put it back on the ordinary path
113	        // rather than failing the handler: capture() then records it unread, and the residue
114	        // assertion reports it unless it is the measured prefetch class.
115	        await route.fallback().catch(() => undefined);
116	      }
117	    },
118	  );
119	
120	  const pending: Promise<Seen>[] = [];
121	  page.on('response', (response) => {
122	    pending.push(capture(response, buffered));
123	  });
124	  const issuedBefore = harness.idp.issued.length;
125	
126	  const { accessToken, refreshToken } = await signIn(page, harness, '/gateway/overview');
127	  await page.goto(harness.url(`/gateway/orgs/${ORG_ID}`));
128	  await waitForHydration(page);
129	
130	  // A client-side navigation, so the RSC payload path is exercised, not only full documents.
131	  const rsc = page.waitForResponse((response) => (response.headers()['content-type'] ?? '').startsWith('text/x-component') && response.request().method() === 'GET');
132	  await page.getByRole('navigation', { name: 'Primary' }).getByRole('link', { name: 'Overview', exact: true }).click();
133	  await rsc;
134	  await page.waitForURL((url) => url.pathname === '/gateway/overview');
135	
136	  const seen = await Promise.all(pending);
137	  const tokens = [accessToken, refreshToken, ...harness.idp.issued.slice(issuedBefore).flatMap((issued) => [issued.accessToken, issued.refreshToken])];
138	  expect(tokens.length).toBeGreaterThanOrEqual(2);
139	  for (const token of tokens) expect(token.length).toBeGreaterThanOrEqual(16);
140	
141	  const leaks = seen.filter((response) => tokens.some((token) => response.text.includes(token))).map((response) => `${response.method} ${response.url}`);
142	  expect(leaks).toEqual([]);
143	
144	  // The RESIDUE: every response that should carry a body, and whose body this row did not read,
145	  // must belong to the one measured class. A positive match, so a NEW unread response reds this
146	  // row instead of leaving the scan quietly smaller.
147	  expect(seen.filter((response) => response.expectsBody && !response.bodyRead && !response.prefetchRsc).map((response) => `${response.method} ${response.url}`)).toEqual([]);
148	  // The census of the scan, so a SHRINKING scan is visible in the log and not only in a red.
149	  console.log(
150	    `R5 scan: ${String(seen.length)} responses, ${String(seen.filter(scanned).length)} scanned, ${String(seen.filter((response) => response.buffered).length)} buffered, ${String(seen.filter((response) => response.expectsBody && !response.bodyRead).length)} unread`,
151	  );
152	
153	  // Vacuity guards: at least one non-empty HTML body and one non-empty RSC body were READ and
154	  // scanned. A response is not enough: if every body read of a kind failed, the scan above
155	  // searched only headers for that kind, and the guard fails.
156	  expect(seen.some((response) => response.contentType.startsWith('text/html') && scanned(response))).toBe(true);
157	  expect(seen.some((response) => response.contentType.startsWith('text/x-component') && scanned(response))).toBe(true);
158	  // Keeps the load regression from returning in silence: an RSC GET body was scanned FROM THE
159	  // ROUTE BUFFER, not merely because response.body() happened to work.
160	  expect(seen.some((response) => response.method === 'GET' && response.contentType.startsWith('text/x-component') && response.buffered && scanned(response))).toBe(true);
161	});

