import pathlib

# --- T2: the worker timeout must budget TWO health probes per attempt ---
p = pathlib.Path('ts/apps/gateway-console/tests/e2e/support/two-zone-harness.ts')
s = p.read_text()
old = """    // The container start on top of the two servers: REDIS_START_TIMEOUT_MS (120 s) for Redis, plus
    // MAX_START_ATTEMPTS * READY_TIMEOUT_MS for the servers, plus room for the three fakes, the
    // forwarder, the terminator, the port probes and the cleanup.
    { scope: 'worker', timeout: REDIS_START_TIMEOUT_MS + MAX_START_ATTEMPTS * READY_TIMEOUT_MS + 60_000 },"""
new = """    // The container start on top of the two servers: REDIS_START_TIMEOUT_MS (120 s) for Redis, plus
    // the server budget, plus room for the three fakes, the forwarder, the terminator, the port
    // probes and the cleanup.
    //
    // The server budget is MAX_START_ATTEMPTS * 2 * READY_TIMEOUT_MS, and the 2 is load-bearing:
    // THIS stack waits on two health endpoints per attempt, and waitForHealth can spend the full
    // READY_TIMEOUT_MS on each before it observes a late child exit. Budgeting one probe per
    // attempt lets this wrapper fire first on a slow start, and Playwright then reports an opaque
    // fixture timeout instead of startStack's aggregated error, which names the server that failed.
    { scope: 'worker', timeout: REDIS_START_TIMEOUT_MS + MAX_START_ATTEMPTS * 2 * READY_TIMEOUT_MS + 60_000 },"""
assert old in s
p.write_text(s.replace(old, new, 1))

# --- T4: R10 gets its own positive control ---
p = pathlib.Path('ts/apps/gateway-console/tests/e2e/two-zone-isolation.spec.ts')
s = p.read_text()
old = """  const connectionsBefore = harness.iamConsole.connections();
  const requestsBefore = harness.iamConsole.requests();"""
new = """  // THIS ROW'S OWN POSITIVE CONTROL, and it may not be moved to another test. A zero delta is
  // also what an unwired forwarder reports — one the terminator never routes to counts nothing
  // and this row would pass having proved no isolation at all. R8 drives traffic through /iam,
  // but R8 is a DIFFERENT test: run this row alone (`--grep R10`), or let Playwright restart the
  // worker after a failure, and R8's traffic never happens. A vacuity guard that lives in another
  // test is not a guard on this one.
  //
  // So: reach the IAM zone through the terminator first, and prove the counter moves.
  const wiringBefore = harness.iamConsole.requests();
  const probe = await page.request.get(harness.url('/iam/healthz'));
  expect(probe.ok(), 'the IAM zone did not answer through the terminator, so this row cannot measure isolation').toBe(true);
  expect(harness.iamConsole.requests() - wiringBefore, 'the counting forwarder is not on the /iam route: a zero delta below would prove nothing').toBeGreaterThan(0);

  const connectionsBefore = harness.iamConsole.connections();
  const requestsBefore = harness.iamConsole.requests();"""
assert old in s
p.write_text(s.replace(old, new, 1))
print('T2 and T4 patched')
